int main(void) {
  char path[PATH_MAX + 1];
  ssize_t size = readlink("/proc/self/exe", path, PATH_MAX);
  if (size < 0) {
    fprintf(stderr, "readlink failed: %s\n", strerror(errno));
    return 1;
  }
  path[size] = '\0';
  printf("app=%s\n", path);
  if (!getcwd(path, sizeof(path))) {
    fprintf(stderr, "getcwd failed: %s\n", strerror(errno));
    return 2;
  }
  printf("cwd=%s\n", path);
  return 0;
}

